using FreeSql; using VelrixWorkHub.Application.Lms; using VelrixWorkHub.Domain;
namespace VelrixWorkHub.Infrastructure.Lms;
public sealed class FreeSqlLmsLicenseProductRepository(IFreeSql fsql) : ILmsLicenseProductRepository { public IReadOnlyList<LmsLicenseProduct> List() => fsql.Select<LmsLicenseProductRecord>().ToList().Select(x => { var p = new LmsLicenseProduct(x.Code, x.Name, x.Description, x.OtherInfo, x.CreatedAt) { Id = x.Id }; p.SetStatus(x.Status); return p; }).ToArray(); public void Add(LmsLicenseProduct x) => fsql.Insert(new LmsLicenseProductRecord { Id = x.Id, Code = x.Code, Name = x.Name, Description = x.Description, OtherInfo = x.OtherInfo, Status = x.Status, CreatedAt = x.CreatedAt }).ExecuteAffrows(); public void Update(LmsLicenseProduct x) { if (fsql.Update<LmsLicenseProductRecord>().Set(a => a.Code, x.Code).Set(a => a.Name, x.Name).Set(a => a.Description, x.Description).Set(a => a.OtherInfo, x.OtherInfo).Set(a => a.Status, x.Status).Where(a => a.Id == x.Id).ExecuteAffrows() == 0) throw new InvalidOperationException("许可证产品不存在。"); } }
